SELECT MIN(eixo_1.data_de_inicio) AS temp(attr:data_de_inicio:ok)(3982078387)(0),   MAX(eixo_1.data_de_inicio) AS temp(attr:data_de_inicio:ok)(86782374)(0),   MIN(eixo_1.data_de_previsaode_termino) AS temp(attr:data_de_previsaode_termino:ok)(4171852708)(0),   MAX(eixo_1.data_de_previsaode_termino) AS temp(attr:data_de_previsaode_termino:ok)(570103144)(0),   CAST(eixo_1.codigo_da_oferta AS BIGINT) AS codigo_da_oferta,   eixo_1.edicao_catalogo_guia AS edicao_catalogo_guia,   eixo_1.nome_do_curso AS nome_do_curso,   eixo_1.situacao_da_turma AS situacao_da_turma,   eixo_1.subtipo_curso AS subtipo_curso,   SUM(CAST(eixo_1.number of records AS BIGINT)) AS sum:number of records:ok,   CAST(EXTRACT(YEAR FROM eixo_1.data_de_inicio) AS BIGINT) AS yr:data_de_inicio:ok FROM eixo_1 WHERE ((eixo_1.nome_do_curso IN ('Agente de Saúde e Bem estar Animal', 'Eletricista de Veículos de Transporte de Cargas e de Passageiros', 'Recepcionista em Meios de Hospedagem', 'RECEPCIONISTA EM MEIOS DE HOSPEDAGEM', 'Soldador no Processo MIG/MAG', 'SOLDADOR NO PROCESSO MIG/MAG', 'Traçador de Caldeiraria', 'TRAÇADOR DE CALDEIRARIA')) AND (NOT (eixo_1.situacao_da_turma IN ('CANCELADA', 'CRIADA', 'PUBLICADA'))) AND (eixo_1.subtipo_curso = 'FIC') AND (CAST(EXTRACT(YEAR FROM eixo_1.data_de_inicio) AS BIGINT) = 2015) AND (NOT ((eixo_1.nome da sit matricula (situacao detalhada) NOT IN ('', 'TRANSF_EXT', 'INTEGRALIZADA', 'FREQ_INIC_INSUF', 'TRANCADA', 'CONCLUÍDA', 'TRANSF_INT', 'EM_CURSO', 'REPROVADA', 'ABANDONO', 'CONFIRMADA', 'EM_DEPENDÊNCIA')) OR (eixo_1.nome da sit matricula (situacao detalhada) IS NULL)))) GROUP BY eixo_1.codigo_da_oferta,   edicao_catalogo_guia,   nome_do_curso,   situacao_da_turma,   subtipo_curso,   yr:data_de_inicio:ok,   codigo_da_oferta;
